'use client';

import React, { useState } from 'react';
import { 
  Calculator, 
  ChevronRight, 
  X, 
  Clock, 
  CheckCircle2, 
  AlertCircle, 
  Ban, 
  Info, 
  ChevronDown 
} from 'lucide-react';
import clsx from 'clsx';
import { calculateCancellationRefund, RefundCalculationResult } from '@/lib/cancellationRefund';

interface CancellationRefundCardProps {
  pnr: string;
  journeyDate: string;
  departureTime?: string;
  fare?: number | null;
  travelClass?: string;
  quota?: string;
  passengers: Array<{
    booking_status?: string;
    current_status?: string;
  }>;
  chartStatus?: string;
}

export function CancellationRefundCard(props: CancellationRefundCardProps) {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [showExceptions, setShowExceptions] = useState(false);
  const [customFare, setCustomFare] = useState<number | null>(props.fare || null);
  const [isEditingFare, setIsEditingFare] = useState(false);

  const result: RefundCalculationResult = calculateCancellationRefund({
    ...props,
    fare: customFare !== null ? customFare : props.fare
  });

  return (
    <>
      {/* ── Main Inline Card (Matching RailCore Benchmark) ── */}
      <button
        type="button"
        onClick={() => setIsModalOpen(true)}
        className="group w-full rounded-3xl md:rounded-[2rem] border border-subtle bg-card/90 p-4 sm:p-5 text-left shadow-card hover:shadow-glow-primary transition-all duration-300 hover:border-primary/40 hover:-translate-y-0.5 cursor-pointer backdrop-blur-xl"
        aria-haspopup="dialog"
      >
        <div className="flex items-center gap-3 sm:gap-4">
          {/* Calculator Icon */}
          <span className="grid h-11 w-11 shrink-0 place-items-center rounded-2xl border border-primary/20 bg-primary/10 text-primary shadow-inner">
            <Calculator className="h-5 w-5" aria-hidden="true" />
          </span>

          {/* Title & Active Time Window Subtitle */}
          <div className="min-w-0 flex-1">
            <h2 className="text-sm md:text-base font-bold leading-tight text-main group-hover:text-primary transition-colors">
              Estimated cancellation refund
            </h2>
            <p className="mt-1 text-xs text-muted leading-relaxed truncate">
              {result.currentSlabLabel} before departure
            </p>
          </div>

          {/* Refund Price Badge */}
          <div className="shrink-0 text-right">
            <p className="text-xl md:text-2xl font-black font-mono tracking-tight text-main">
              ₹{result.currentRefund.toLocaleString('en-IN')}
            </p>
            <p className="text-[10px] md:text-[11px] font-semibold text-muted">
              if cancelled now
            </p>
          </div>

          {/* Arrow Chevron Button */}
          <span className="grid h-8 w-8 shrink-0 place-items-center rounded-full border border-subtle bg-input/40 text-muted transition-all group-hover:border-primary/40 group-hover:bg-primary/10 group-hover:text-primary">
            <ChevronRight className="h-4 w-4" aria-hidden="true" />
          </span>
        </div>
      </button>

      {/* ── Detailed Refund Estimation Modal (Matching RailCore Exact Popup) ── */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in duration-200">
          <div 
            className="relative w-full max-w-lg max-h-[92vh] overflow-y-auto rounded-[2rem] border border-subtle bg-card p-6 md:p-7 shadow-2xl space-y-5 animate-in zoom-in-95 duration-200"
            role="dialog"
            aria-modal="true"
          >
            {/* Modal Header */}
            <div className="flex items-center justify-between pb-3 border-b border-subtle/80">
              <div>
                <p className="text-[10px] font-black uppercase tracking-widest text-muted">
                  Before you cancel
                </p>
                <h3 className="text-xl font-black text-main tracking-tight mt-0.5">
                  Estimated refund
                </h3>
              </div>
              <button
                type="button"
                onClick={() => setIsModalOpen(false)}
                className="grid h-9 w-9 place-items-center rounded-full border border-subtle bg-input/40 text-muted hover:text-main hover:border-subtle hover:bg-input transition-colors"
                aria-label="Close"
              >
                <X size={18} />
              </button>
            </div>

            {/* Top Highlight Box (Estimated Refund If Cancelled Now) */}
            <div className="rounded-2xl border border-amber-500/30 bg-amber-500/[0.08] dark:bg-amber-500/[0.12] p-4 sm:p-5 space-y-2">
              <div className="flex items-center justify-between gap-2">
                <span className="text-[10px] font-black uppercase tracking-wider text-muted">
                  Estimated refund if cancelled now
                </span>
                <span className="rounded-full border border-amber-500/30 bg-card px-2.5 py-0.5 text-[10px] font-bold text-amber-600 dark:text-amber-400 shadow-sm">
                  {result.currentSlabWindow}
                </span>
              </div>

              <div className="text-3xl sm:text-4xl font-black font-mono text-main tracking-tight">
                ₹{result.currentRefund.toLocaleString('en-IN')}
              </div>

              <div className="flex flex-wrap items-center justify-between text-xs text-muted gap-2 pt-0.5">
                <span>
                  Ticket fare <strong className="text-main">₹{result.ticketFare.toLocaleString('en-IN')}</strong> · estimated deduction <strong className="text-rose-500 dark:text-rose-400">₹{result.currentDeduction.toLocaleString('en-IN')}</strong>
                </span>
                <button
                  type="button"
                  onClick={() => setIsEditingFare(!isEditingFare)}
                  className="text-[10px] font-bold text-primary hover:underline"
                >
                  {isEditingFare ? 'Close Edit' : 'Edit Fare'}
                </button>
              </div>

              {/* Fare editor input */}
              {isEditingFare && (
                <div className="mt-3 pt-3 border-t border-amber-500/20 flex items-center gap-2">
                  <input
                    type="number"
                    min="0"
                    placeholder="Enter fare"
                    defaultValue={result.ticketFare}
                    onChange={(e) => {
                      const val = parseFloat(e.target.value);
                      if (!isNaN(val) && val >= 0) setCustomFare(val);
                    }}
                    className="w-32 px-3 py-1.5 text-xs font-mono font-bold bg-input border border-subtle rounded-xl text-main outline-none focus:border-primary"
                  />
                  <button
                    type="button"
                    onClick={() => setIsEditingFare(false)}
                    className="text-xs font-bold px-3 py-1.5 rounded-xl bg-primary text-white"
                  >
                    Apply
                  </button>
                </div>
              )}

              {/* Countdown detail */}
              <div className="pt-2 border-t border-amber-500/20 flex items-start gap-2 text-xs text-secondary leading-relaxed">
                <Clock size={15} className="text-amber-500 shrink-0 mt-0.5" />
                <span>
                  {result.timeUntilDepartureText} until departure. {result.explanation}
                </span>
              </div>
            </div>

            {/* Fare Summary Strip */}
            <div className="flex flex-wrap items-center justify-between rounded-xl bg-input/40 border border-subtle/70 px-4 py-2.5 text-xs text-muted">
              <span>Fare <strong className="text-main">₹{result.ticketFare.toLocaleString('en-IN')}</strong></span>
              <span>Passengers <strong className="text-main">{result.passengerCount}</strong></span>
              <span>Class <strong className="text-main">{result.travelClass}</strong></span>
              {result.isTatkal && (
                <span className="text-amber-600 dark:text-amber-400 font-bold">Quota {result.quota}</span>
              )}
            </div>

            {/* How Timing Changes The Refund (4 Slabs Table) */}
            <div className="space-y-2.5">
              <h4 className="text-xs font-bold uppercase tracking-wider text-muted">
                How timing changes the refund
              </h4>

              <div className="divide-y divide-subtle/60 rounded-2xl border border-subtle bg-input/20 overflow-hidden">
                {result.slabs.map((slab) => (
                  <div
                    key={slab.key}
                    className={clsx(
                      "flex items-center justify-between p-3.5 text-xs transition-colors",
                      slab.isActive
                        ? "bg-amber-500/10 dark:bg-amber-500/15 font-bold"
                        : "hover:bg-input/30"
                    )}
                  >
                    <div className="flex items-start gap-2.5 min-w-0 pr-2">
                      <div className="mt-0.5 shrink-0">
                        {slab.key === 'gt48' ? (
                          <CheckCircle2 size={16} className="text-emerald-500" />
                        ) : slab.key === 'lt4' ? (
                          <Ban size={16} className="text-rose-500" />
                        ) : (
                          <Clock size={16} className={slab.isActive ? "text-amber-500" : "text-muted"} />
                        )}
                      </div>
                      <div className="min-w-0">
                        <div className="flex items-center gap-2">
                          <span className={clsx("font-bold text-main", slab.isActive && "text-amber-600 dark:text-amber-400")}>
                            {slab.label}
                          </span>
                          {slab.isActive && (
                            <span className="rounded-full bg-amber-500 text-white text-[9px] font-black px-1.5 py-0.2 tracking-wider">
                              NOW
                            </span>
                          )}
                        </div>
                        <p className="text-[11px] text-muted truncate mt-0.5">
                          {slab.percentageText}
                        </p>
                      </div>
                    </div>

                    <div className="text-right shrink-0">
                      <p className={clsx("text-sm font-bold font-mono", slab.refundAmount > 0 ? "text-main" : "text-muted")}>
                        ₹{slab.refundAmount.toLocaleString('en-IN')}
                      </p>
                      <p className="text-[10px] text-muted">
                        estimated
                      </p>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Accordion: Exceptions & Calculation Notes */}
            <div className="border border-subtle/80 rounded-2xl bg-input/20 p-3.5 space-y-2">
              <button
                type="button"
                onClick={() => setShowExceptions(!showExceptions)}
                className="w-full flex items-center justify-between text-xs font-bold text-main hover:text-primary transition-colors"
              >
                <div className="flex items-center gap-2">
                  <Info size={14} className="text-primary" />
                  <span>Exceptions and calculation notes</span>
                </div>
                <ChevronDown
                  size={15}
                  className={clsx("text-muted transition-transform", showExceptions && "rotate-180")}
                />
              </button>

              {showExceptions && (
                <ul className="mt-2.5 space-y-2 text-xs text-muted leading-relaxed border-t border-subtle/50 pt-2.5 list-disc pl-4 font-sans">
                  <li>Waitlisted and RAC e-tickets not cleared at charting are normally cancelled automatically, with clerkage deducted.</li>
                  <li>Confirmed Tatkal tickets generally carry no refund on passenger cancellation under strict IRCTC rules.</li>
                  <li>A railway-cancelled train, or a delay over 3:00 hr when you do not travel, can qualify for a full refund.</li>
                  <li>GST at 5% applies to the cancellation charge on AC classes.</li>
                  <li>Counter-ticket cancellation timings differ from e-tickets.</li>
                </ul>
              )}

              <p className="text-[11px] text-muted flex items-center gap-1.5 pt-1">
                <Info size={12} className="shrink-0 text-muted" />
                <span>Estimate only; the amount actually credited by IRCTC is final.</span>
              </p>
            </div>
          </div>
        </div>
      )}
    </>
  );
}
