export interface PnrPassengerDisplayInput {
  name?: string;
  booking_status?: string;
  current_status?: string;
  coach?: string;
  coupe?: string;
  berth?: string | number;
  berth_type?: string;
}

export interface ParsedPnrSeatDisplay {
  isCnf: boolean;
  isRac: boolean;
  isWl: boolean;
  isCan: boolean;
  isUnknown: boolean;
  statusBadgeLabel: string;
  coach: string | null;
  coupe: string | null;
  berth: string | null;
  berthType: string | null;
  berthTypeDesc: string | null;
  seatAllotment: string;
  seatAllotmentShort: string;
}

const BERTH_TYPE_MAP: Record<string, string> = {
  LB: 'Lower Berth',
  MB: 'Middle Berth',
  UB: 'Upper Berth',
  SL: 'Side Lower',
  SU: 'Side Upper',
  SM: 'Side Middle',
  WS: 'Window Seat',
  CB: 'Cabin',
  CP: 'Coupe',
};

const BERTH_SHORT_DESC_MAP: Record<string, string> = {
  LB: 'Lower',
  MB: 'Middle',
  UB: 'Upper',
  SL: 'Side Lower',
  SU: 'Side Upper',
  SM: 'Side Middle',
  WS: 'Window Seat',
  CB: 'Cabin',
  CP: 'Coupe',
};

const TERMINAL_RE =
  /(?:ERROR|FAIL|INVALID)|\b(CANCELLED|CANCELED|CAN|MOD|RELEASED|REL|NOSB|UNAVAILABLE|NOT\s+AVAILABLE|NO\s+SEATS|NO\s+ROOM|REGRET|BLOCKED|DEPARTED)\b/i;

const WAITLIST_RE = /\b(WL|WAITLIST|GNWL|RLWL|PQWL|TQWL|CKWL|RSWL|LDWL|SSWL)\b|WAIT/i;

// Matches e.g. "H1 , G - 19 [COUPE]" or "HA1, A - 3 [CABIN]"
const FIRST_AC_COUPE_RE =
  /^(H\d+|HA\d+)\s*[,\/-]\s*([A-Z]{1,2})\s*[-/]\s*(\d+)(?:\s*\[(?:COUPE|CABIN|CB|CP)\])?/i;

// Matches e.g. "B2 - 24", "S3/45", "A1, 12" (excludes WL/RAC via negative lookahead)
const COACH_BERTH_DIRECT_RE = /^([A-Z]{1,3}\d+)\s*[,\/-]\s*(\d+)/i;

export function resolveDisplayCoachForRake(
  coachRaw?: string,
  currentStatus?: string,
  travelClass?: string
): string {
  const cur = (currentStatus || '').trim();
  const coupeMatch = cur.match(FIRST_AC_COUPE_RE);
  if (coupeMatch) {
    return coupeMatch[1].toUpperCase();
  }

  const cleanedCoach = (coachRaw || '').toUpperCase().trim();
  const cleanedClass = (travelClass || '').toUpperCase().trim();

  // If API returned standalone 1A coupe letter (A-H) as coach, map to primary First AC coach H1
  if (/^[A-H]$/.test(cleanedCoach) && (cleanedClass === '1A' || /\[(?:COUPE|CABIN)\]/i.test(cur))) {
    return 'H1';
  }

  return cleanedCoach;
}

export function parsePnrPassengerSeat(
  p: PnrPassengerDisplayInput,
  curWlPos: number | null = null,
  bkgWlPos: number | null = null
): ParsedPnrSeatDisplay {
  const bkgRaw = (p.booking_status || '').trim();
  const curRaw = (p.current_status || '').trim();
  const curUpper = curRaw.toUpperCase();

  const extractSlashOrSpace = (str: string) => {
    const coupeM = str.match(FIRST_AC_COUPE_RE);
    if (coupeM) {
      return {
        status: 'CNF',
        coach: coupeM[1].toUpperCase(),
        coupe: coupeM[2].toUpperCase(),
        berth: coupeM[3],
        bType: /CABIN/i.test(str) ? 'CB' : /COUPE/i.test(str) ? 'CP' : '',
      };
    }

    const slashes = str.split('/').map((s) => s.trim()).filter(Boolean);
    if (slashes.length >= 3) {
      return {
        status: slashes[0],
        coach: slashes[1].toUpperCase(),
        coupe: null as string | null,
        berth: slashes[2],
        bType: slashes[3]?.toUpperCase() || '',
      };
    }

    const spaces = str.split(/[, ]+/).map((s) => s.trim()).filter(Boolean);
    if (spaces.length >= 3 && /^(CNF|RAC)/i.test(spaces[0])) {
      return {
        status: spaces[0],
        coach: spaces[1].toUpperCase(),
        coupe: null as string | null,
        berth: spaces[2],
        bType: spaces[3]?.toUpperCase() || '',
      };
    }

    const directM = str.match(COACH_BERTH_DIRECT_RE);
    if (directM && !WAITLIST_RE.test(str) && !/\bRAC\b/i.test(str)) {
      return {
        status: 'CNF',
        coach: directM[1].toUpperCase(),
        coupe: null as string | null,
        berth: directM[2],
        bType: '',
      };
    }

    return null;
  };

  const curParts = extractSlashOrSpace(curRaw);
  const bkgParts = extractSlashOrSpace(bkgRaw);
  const effectiveParts = curParts || bkgParts;

  const isCan = TERMINAL_RE.test(curUpper);
  const isRac = !isCan && /\bRAC\b/i.test(curUpper);
  const isExplicitKeywordCnf =
    !isCan &&
    !isRac &&
    !WAITLIST_RE.test(curUpper) &&
    /\b(CNF|CONFIRMED|CONFIRM|AVAILABLE|AVL)\b/i.test(curUpper);
  const isCoachBerthCnf =
    !isCan &&
    !isRac &&
    !WAITLIST_RE.test(curUpper) &&
    Boolean(curParts?.coach && curParts?.berth && /^\d+$/.test(String(curParts.berth)));

  const isCnf = isExplicitKeywordCnf || isCoachBerthCnf;
  const isWl = !isCnf && !isRac && !isCan && (WAITLIST_RE.test(curUpper) || curWlPos !== null);
  const isUnknown = !isCnf && !isRac && !isCan && !isWl;

  // Prefer parent coach (e.g. H1) when curParts detected a 1A coupe/cabin string
  const rawCoach = p.coach ? String(p.coach).toUpperCase().trim() : null;
  const coach =
    curParts?.coupe && curParts.coach
      ? curParts.coach
      : rawCoach || effectiveParts?.coach || null;
  const coupe = (p.coupe ? String(p.coupe).toUpperCase().trim() : null) || curParts?.coupe || null;
  const berthVal = p.berth !== undefined && p.berth !== null && String(p.berth).trim() !== ''
    ? String(p.berth).trim()
    : effectiveParts?.berth || null;
  const rawBType = p.berth_type ? String(p.berth_type).toUpperCase().trim() : '';
  const berthType = rawBType || effectiveParts?.bType || null;
  const berthTypeDesc = berthType ? BERTH_TYPE_MAP[berthType] || berthType : null;
  const shortDesc = berthType ? BERTH_SHORT_DESC_MAP[berthType] || berthType : null;

  let statusBadgeLabel = curRaw || 'Unknown';
  if (isCnf) statusBadgeLabel = 'CNF';
  else if (curParts?.status) statusBadgeLabel = curParts.status;

  const coupeSegment = coupe ? ` • Coupe ${coupe}` : '';
  const shortCoupeSegment = coupe ? ` (${coupe})` : '';

  let seatAllotment = '--';
  let seatAllotmentShort = '--';
  if (isCnf) {
    if (coach && berthVal) {
      const descText = berthTypeDesc || shortDesc;
      seatAllotment = descText
        ? `Coach ${coach}${coupeSegment} • Berth ${berthVal} (${descText})`
        : `Coach ${coach}${coupeSegment} • Berth ${berthVal}`;
      seatAllotmentShort = berthType
        ? `${coach}${shortCoupeSegment}, ${berthVal} (${berthType})`
        : `${coach}${shortCoupeSegment}, ${berthVal}`;
    } else {
      seatAllotment = 'Confirmed (Berth pending chart)';
      seatAllotmentShort = 'CNF (Pending)';
    }
  } else if (isRac) {
    if (coach && berthVal) {
      seatAllotment = `Coach ${coach} • Seat ${berthVal} (Sitting)`;
      seatAllotmentShort = `${coach}, ${berthVal} (RAC)`;
    } else {
      seatAllotment = curWlPos !== null ? `RAC Seat #${curWlPos}` : 'RAC Sitting Berth';
      seatAllotmentShort = curWlPos !== null ? `RAC #${curWlPos}` : 'RAC';
    }
  } else if (isWl) {
    const wlMatch = curRaw.match(/\d+/);
    const pos = wlMatch ? wlMatch[0] : bkgWlPos !== null ? `${bkgWlPos}` : '';
    seatAllotment = pos ? `Queue Position #${pos}` : 'Waitlist';
    seatAllotmentShort = pos ? `WL #${pos}` : 'Waitlist';
  } else if (isCan) {
    seatAllotment = 'Ticket Cancelled';
    seatAllotmentShort = 'Cancelled';
  }

  return {
    isCnf,
    isRac,
    isWl,
    isCan,
    isUnknown,
    statusBadgeLabel,
    coach,
    coupe,
    berth: berthVal,
    berthType,
    berthTypeDesc: shortDesc,
    seatAllotment,
    seatAllotmentShort,
  };
}
